 // Package validate checks user-supplied item fields.
+//
+// Checks are expressed as Rules and composed into a Validator, so a field's
+// requirements can be extended or reordered without touching the callers.
 package validate

 import (
 	"errors"
 	"fmt"
+	"strings"
 	"unicode/utf8"
 )

 // MaxNameLen is the longest name accepted, in runes.
 const MaxNameLen = 64

 // ErrInvalid wraps every validation failure.
 var ErrInvalid = errors.New("invalid")

-// Name checks that a name is usable as an item name.
-func Name(name string) error {
-	if utf8.RuneCountInString(name) > MaxNameLen {
-		return fmt.Errorf("%w: name longer than %d characters", ErrInvalid, MaxNameLen)
-	}
-	for _, r := range name {
-		if r == '\n' || r == '\t' || r == '\r' {
-			return fmt.Errorf("%w: name contains control characters", ErrInvalid)
+// Rule checks one property of a value.
+type Rule interface {
+	Check(value string) error
+}
+
+// RuleFunc adapts a plain function to Rule.
+type RuleFunc func(value string) error
+
+// Check implements Rule.
+func (f RuleFunc) Check(value string) error { return f(value) }
+
+// Validator runs its rules in order and returns the first failure.
+type Validator struct {
+	rules []Rule
+}
+
+// NewValidator builds a validator from rules, applied in the order given.
+func NewValidator(rules ...Rule) *Validator {
+	return &Validator{rules: rules}
+}
+
+// With returns a copy of v with extra rules appended.
+func (v *Validator) With(rules ...Rule) *Validator {
+	return NewValidator(append(append([]Rule{}, v.rules...), rules...)...)
+}
+
+// Validate applies every rule to value.
+func (v *Validator) Validate(value string) error {
+	for _, r := range v.rules {
+		if err := r.Check(value); err != nil {
+			return err
 		}
 	}
 	return nil
 }
+
+// NotEmpty rejects values that are empty or whitespace only.
+func NotEmpty() Rule {
+	return RuleFunc(func(value string) error {
+		if strings.TrimSpace(value) == "" {
+			return fmt.Errorf("%w: name is empty", ErrInvalid)
+		}
+		return nil
+	})
+}
+
+// MaxLen rejects values longer than n runes.
+func MaxLen(n int) Rule {
+	return RuleFunc(func(value string) error {
+		if utf8.RuneCountInString(value) > n {
+			return fmt.Errorf("%w: name longer than %d characters", ErrInvalid, n)
+		}
+		return nil
+	})
+}
+
+// NoControlChars rejects values containing newlines or tabs.
+func NoControlChars() Rule {
+	return RuleFunc(func(value string) error {
+		for _, r := range value {
+			if r == '\n' || r == '\t' || r == '\r' {
+				return fmt.Errorf("%w: name contains control characters", ErrInvalid)
+			}
+		}
+		return nil
+	})
+}
+
+// NameValidator is the rule set applied to item names.
+var NameValidator = NewValidator(NotEmpty(), MaxLen(MaxNameLen), NoControlChars())
+
+// Name checks that a name is usable as an item name.
+func Name(name string) error {
+	return NameValidator.Validate(name)
+}
